        --counts[second[i] - 'a'];
    }
    bool anagram = true;
    for (int i = 0; i < 26; ++i) if (counts[i] != 0) anagram = false;
    cout << (anagram ? "Yes! It's anagram.\n" : "No! It is not anagram.\n");
}

// 2021 final E: the prescribed encrypt class, with spaces preserved.
#include <iostream>
#include <limits>
#include <string>
using namespace std;

class encrypt {
public:
    explicit encrypt(string text) : information(text) {}
    void encryption() {
        for (size_t i = 0; i < information.size(); ++i) {
            if (information[i] == ' ') continue;
            const int value = static_cast<unsigned char>(information[i]);
            const int changed = i % 2 == 0 ? value + key * key : value - key;
            information[i] = static_cast<char>(static_cast<unsigned char>(changed));
        }
    }
    void decryption() {
        for (size_t i = 0; i < information.size(); ++i) {
            if (information[i] == ' ') continue;
            const int value = static_cast<unsigned char>(information[i]);
            const int changed = i % 2 == 0 ? value - key * key : value + key;
            information[i] = static_cast<char>(static_cast<unsigned char>(changed));
        }
    }
    void print_information() { cout << information << '\n'; }
private:
    string information;
    int key = 3;
};
int main() {
    cout << "Welcome to encryption system!\nEnter 1 to encrypt\nEnter 2 to decrypt\n";
    int mode;
    if (!(cin >> mode) || (mode != 1 && mode != 2)) { cout << "error\n"; return 1; }
    cin.ignore(numeric_limits<streamsize>::max(), '\n');
    cout << "\nInput information: ";
    string information;
    if (!getline(cin, information)) return 1;
    if (!information.empty() && information.back() == '\r') information.pop_back();
    encrypt message(information);
    if (mode == 1) { message.encryption(); cout << "Encrypted information: "; }
    else { message.decryption(); cout << "Decrypted information: "; }
    message.print_information();
}

// 2021 final F: infer N from all scores up to EOF; round to two decimal places.
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
using namespace std;
int main() {
    cout << "Please enter the scores of all students:\n";
    int scores[50], count = 0, sum = 0;
    string token;
    while (cin >> token) {
        istringstream parser(token);
        int score;
        if (!(parser >> score) || parser.peek() != char_traits<char>::eof() ||
            score < 0 || score > 100 || count == 50) { cout << "error\n"; return 1; }
        scores[count++] = score;
        sum += score;
    }
    if (!cin.eof() || count == 0) { cout << "error\n"; return 1; }
    const int rounded = (sum * 100 + count / 2) / count;
    const int fraction = rounded % 100;
    cout << "avg = " << rounded / 100;
    if (fraction) {
        cout << '.';
        if (fraction % 10 == 0) cout << fraction / 10;
        else cout << setfill('0') << setw(2) << fraction;
    }
    cout << '\n';
    bool failed = false;
    for (int i = 0; i < count; ++i) if (scores[i] < 70) failed = true;
    if (failed) {
        cout << "fail:\n";
        for (int i = 0; i < count; ++i) if (scores[i] < 70) cout << i + 1 << ": " << scores[i] << '\n';
    }
}

